package com.aoo.bcg.poker.cx;
import com.aoo.bcg.gamespi.*;
import com.aoo.bcg.gamespi.time.OperationDeadline;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
final class CxSceneProgressTest {
 private CxSession terminal(){var s=new CxSession(9001,101,7,CxRules.from(Map.of()));s.sit(101L,100,"initial-a");s.sit(102L,100,"initial-b");var state=new LinkedHashMap<>(s.authoritativeState());state.put("phase","FINISHED");state.put("terminalDeadlineEpochMillis",System.currentTimeMillis()+60000);state.put("operationDeadline",OperationDeadline.none().toMap());return CxSession.restore(state);}
 private int seat(CxSession s,long actor){return ((Number)s.viewFor(actor).get("viewerSeat")).intValue();}
 private void request(CxSession s,String action,String id,long actor,long amount){s.execute(new GameCommandRequest("poker.chengdu2999."+action+"_req",id,1,9001,0,CxRules.VERSION,Long.toString(actor),seat(s,actor),Map.of("carryScore",amount)));}
 @SuppressWarnings("unchecked") private Map<String,Object> progress(CxSession s){return (Map<String,Object>)s.authoritativeState().get("sceneProgress");}
 @SuppressWarnings("unchecked") private List<Map<String,Object>> attempts(CxSession s){return (List<Map<String,Object>>)progress(s).get("attempts");}
 private Map<String,Object> attempt(CxSession s,String id){return attempts(s).stream().filter(x->x.get("originalRestartRequestId").equals(id)).findFirst().orElseThrow();}
 @Test void pendingRestoresExactOriginalRequestAndIsInternal(){var s=terminal();request(s,"restart","original-A",101,200);assertEquals("PENDING",attempt(s,"original-A").get("status"));assertEquals(0L,progress(s).get("sceneOrdinal"));assertEquals(1L,attempt(s,"original-A").get("targetSceneOrdinal"));var restored=CxSession.restore(s.authoritativeState());assertEquals(s.authoritativeState(),restored.authoritativeState());assertFalse(s.viewFor(101).containsKey("sceneProgress"));}
 @Test void supersedingPendingAbortsOriginalWithoutLosingHistory(){var s=terminal();request(s,"restart","old",101,200);request(s,"restart","new",101,300);assertEquals("ABORTED",attempt(s,"old").get("status"));assertEquals("SUPERSEDED",attempt(s,"old").get("abortReason"));assertEquals("PENDING",attempt(s,"new").get("status"));assertEquals(2,attempts(s).size());assertEquals(s.authoritativeState(),CxSession.restore(s.authoritativeState()).authoritativeState());}
 @Test void standAbortsPendingButDoesNotCreateScene(){var s=terminal();request(s,"restart","waiting",101,200);request(s,"stand","leave",101,0);assertEquals("ABORTED",attempt(s,"waiting").get("status"));assertEquals("SEAT_REMOVED",attempt(s,"waiting").get("abortReason"));assertEquals(0L,progress(s).get("sceneOrdinal"));}
 @Test void trueRestartBatchCommitsFirstOpeningOnceAndOrdinalSurvivesNextSeries(){var s=terminal();request(s,"restart","A",101,200);request(s,"restart","B",102,300);assertEquals(1L,progress(s).get("sceneOrdinal"));assertEquals("BETTING",s.authoritativeState().get("phase"));for(String id:List.of("A","B")){assertEquals("FIRST_OPENING_COMMITTED",attempt(s,id).get("status"));assertTrue(((Number)attempt(s,id).get("firstOpeningStateVersion")).longValue()>=((Number)attempt(s,id).get("appliedStateVersion")).longValue());}var state=new LinkedHashMap<>(s.authoritativeState());state.put("phase","FINISHED");state.put("terminalDeadlineEpochMillis",System.currentTimeMillis()+60000);state.put("operationDeadline",OperationDeadline.none().toMap());s=CxSession.restore(state);request(s,"restart","C",101,200);request(s,"restart","D",102,300);assertEquals(2L,progress(s).get("sceneOrdinal"));assertEquals(1L,attempt(s,"A").get("targetSceneOrdinal"));assertEquals(2L,attempt(s,"C").get("targetSceneOrdinal"));assertEquals("FIRST_OPENING_COMMITTED",attempt(s,"A").get("status"));assertEquals(s.authoritativeState(),CxSession.restore(s.authoritativeState()).authoritativeState());}
 @Test void duplicateDoesNotAllocateOrConsumeCapacity(){var s=terminal();request(s,"restart","once",101,200);var before=s.authoritativeState();assertThrows(IllegalStateException.class,()->request(s,"restart","once",101,200));assertEquals(before,s.authoritativeState());assertEquals(1,attempts(s).size());}
 @Test void legacyHasNoHistoricalProofAndMalformedReferencesReject(){var s=terminal();var legacy=new LinkedHashMap<>(s.authoritativeState());legacy.remove("sceneProgress");var restored=CxSession.restore(legacy);assertTrue(attempts(restored).isEmpty());assertEquals(0L,progress(restored).get("sceneOrdinal"));request(restored,"restart","new-proof",101,200);var state=new LinkedHashMap<>(restored.authoritativeState());var proof=new LinkedHashMap<>(progress(restored));proof.put("pendingBySeat",Map.of(seat(restored,101),"unknown-request"));state.put("sceneProgress",proof);assertThrows(IllegalArgumentException.class,()->CxSession.restore(state));}
 @Test void capacityAndOverflowRejectBeforeAnyNativeMutation(){var s=terminal();var state=new LinkedHashMap<>(s.authoritativeState());List<Map<String,Object>> history=new ArrayList<>();for(int i=0;i<4096;i++)history.add(Map.of("originalRestartRequestId","history-"+i,"actorId",101L,"seatId",0,"targetSceneOrdinal",1L,"status","ABORTED","acceptedStateVersion",0L,"abortReason","SUPERSEDED"));state.put("sceneProgress",Map.of("schemaVersion",1,"sceneOrdinal",0L,"attempts",history,"pendingBySeat",Map.of(),"activeSceneAttempts",List.of()));var full=CxSession.restore(state);var before=full.authoritativeState();assertThrows(IllegalStateException.class,()->request(full,"restart","over-cap",101,200));assertEquals(before,full.authoritativeState());state=new LinkedHashMap<>(s.authoritativeState());state.put("sceneProgress",Map.of("schemaVersion",1,"sceneOrdinal",Long.MAX_VALUE,"attempts",List.of(),"pendingBySeat",Map.of(),"activeSceneAttempts",List.of()));var overflow=CxSession.restore(state);before=overflow.authoritativeState();assertThrows(ArithmeticException.class,()->request(overflow,"restart","overflow",101,200));assertEquals(before,overflow.authoritativeState());}
 @Test void insufficientActualOpeningDoesNotFabricateCommittedFact(){var s=terminal();request(s,"restart","unfunded-A",101,0);request(s,"restart","unfunded-B",102,0);assertEquals(1L,progress(s).get("sceneOrdinal"));assertEquals("FINISHED",s.authoritativeState().get("phase"));assertEquals("ABORTED",attempt(s,"unfunded-A").get("status"));assertFalse(attempt(s,"unfunded-A").containsKey("firstOpeningStateVersion"));}
    @Test void presentNullSceneFieldsRejectButWholeMissingIsLegacy(){var s=terminal();var legacy=new LinkedHashMap<>(s.authoritativeState());legacy.remove("sceneProgress");assertDoesNotThrow(()->CxSession.restore(legacy));for(String key:List.of("sceneProgress","schemaVersion","attempts","pendingBySeat","activeSceneAttempts")){var state=new LinkedHashMap<>(s.authoritativeState());if(key.equals("sceneProgress"))state.put(key,null);else{var proof=new LinkedHashMap<>(progress(s));proof.put(key,null);state.put("sceneProgress",proof);}assertThrows(IllegalArgumentException.class,()->CxSession.restore(state));}}
    @Test void presentNullRequiredAttemptRequestRejects(){var s=terminal();request(s,"restart","nonnull",101,200);var state=new LinkedHashMap<>(s.authoritativeState());var proof=new LinkedHashMap<>(progress(s));var row=new LinkedHashMap<>(attempt(s,"nonnull"));row.put("originalRestartRequestId",null);proof.put("attempts",List.of(row));state.put("sceneProgress",proof);assertThrows(IllegalArgumentException.class,()->CxSession.restore(state));}
    @Test void restoreRejectsPresentNullSceneProgress(){var s=terminal();var state=new LinkedHashMap<>(s.authoritativeState());state.put("sceneProgress",null);assertThrows(IllegalArgumentException.class,()->CxSession.restore(state));}
}
